import { renderWorkbenchShell } from "./ui/dashboard";
import type { WorkbenchState, WorkbenchRenderArgs } from "./ui/dashboard";
import css from "./styles.css";

const initialState: WorkbenchState = {
  jsonOpen: false,
  libraryOpen: false,
  spaceOpen: false,
};

export function composeRender(): string {
  const dom = new (globalThis as unknown as {
    DOM: new () => {
      createClassFromStyle(style: string): string;
      renderHTML(html: string): string;
    };
  }).DOM();

  const args: WorkbenchRenderArgs = {
    shellClass: dom.createClassFromStyle(css.shell),
    dashboardClass: dom.createClassFromStyle(css.dashboard),
    cardClass: dom.createClassFromStyle(css.card),
    libraryClass: dom.createClassFromStyle(css.library),
    workspaceClass: dom.createClassFromStyle(css.workspace),
    resultClass: dom.createClassFromStyle(css.result),
    dockClass: dom.createClassFromStyle(css.dock),
  };

  const html = renderWorkbenchShell(initialState, args);
  return dom.renderHTML(html);
}
